package dev.veltraph.client.garden.pests;

import dev.veltraph.client.world.Vec3;
import dev.veltraph.client.config.*;
import dev.veltraph.client.ui.content.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

final class NearbyPestTrackerTest {
    private final NearbyPestTracker tracker=new NearbyPestTracker();private final Object entity=new Object();private final UUID uuid=UUID.randomUUID();
    private final NearbyPestTracker.Scope scope=new NearbyPestTracker.Scope(new Object(),new Object(),new Object(),new Object(),new Object(),new Object(),"observed-policy",1);
    private final NearbyPestTracker.Settings settings=new NearbyPestTracker.Settings(90,3,.5);
    private NearbyPestTracker.Observation frame(long tick,Object e,UUID id,Vec3 p,Vec3 goal,float yaw,boolean visible){return new NearbyPestTracker.Observation(scope,tick,p,yaw,new NearbyPestTracker.Target(e,5,id,"exact observed model",goal),visible,4.5);}
    private NearbyPestTracker.Observation frame(long tick){return frame(tick,entity,uuid,new Vec3(0,72,0),new Vec3(0,72,3),0,true);}
    private boolean ready(long tick){return tracker.observe(frame(tick),settings).isPresent();}
    @Test void sameMovingNativeTargetDwellUsesFreshGeometry(){for(int i=0;i<3;i++)assertFalse(tracker.observe(frame(i,entity,uuid,new Vec3(i*.1,72,0),new Vec3(i*.1,72,3),0,true),settings).isPresent());assertTrue(tracker.observe(frame(3,entity,uuid,new Vec3(.3,72,0),new Vec3(.3,72,3),0,true),settings).isPresent());}
    @Test void replacementCannotBorrowPreviousTargetDwell(){ready(0);ready(1);ready(2);Object replacement=new Object();assertTrue(tracker.observe(frame(3,replacement,uuid,new Vec3(0,72,0),new Vec3(0,72,3),0,true),settings).isEmpty());}
    @Test void sameObjectWithDifferentUuidOrNativeIdOrModelResets(){for(int kind=0;kind<3;kind++){tracker.reset();ready(0);ready(1);ready(2);var f=frame(3);var t=f.target();var changed=new NearbyPestTracker.Target(t.nativeEntity(),kind==1?6:5,kind==0?UUID.randomUUID():uuid,kind==2?"different model":t.model(),t.eye());assertTrue(tracker.observe(new NearbyPestTracker.Observation(scope,3,f.playerEye(),0,changed,true,4.5),settings).isEmpty());}}
    @Test void lostLosAndRangeRestartFullDwell(){ready(0);ready(1);assertTrue(tracker.observe(frame(2,entity,uuid,new Vec3(0,72,0),new Vec3(0,72,3),0,false),settings).isEmpty());assertFalse(ready(3));assertFalse(ready(4));assertFalse(ready(5));assertTrue(ready(6));tracker.reset();ready(0);ready(1);assertTrue(tracker.observe(frame(2,entity,uuid,new Vec3(0,72,0),new Vec3(0,72,4.01),0,true),settings).isEmpty());assertFalse(ready(3));}
    @Test void yawSeamAndInclusiveBoundariesAreGeometric(){double a=Math.toRadians(-179);var f=frame(0,entity,uuid,new Vec3(0,72,0),new Vec3(-Math.sin(a)*4,72,Math.cos(a)*4),179,true);assertTrue(NearbyPestTracker.eligible(f,new NearbyPestTracker.Settings(5,3,.5)));assertFalse(NearbyPestTracker.eligible(f,new NearbyPestTracker.Settings(3,3,.5)));assertTrue(NearbyPestTracker.eligible(frame(0,entity,uuid,new Vec3(0,72,0),new Vec3(-Math.sqrt(8),72,Math.sqrt(8)),0,true),settings));}
    @Test void tickGapDuplicateAndRollbackCannotAddDwell(){ready(0);ready(1);assertFalse(ready(4));assertFalse(ready(5));assertFalse(ready(5));assertFalse(ready(6));assertFalse(ready(7));assertFalse(ready(8));assertTrue(ready(9));assertFalse(ready(8));}
    @Test void discontinuousPlayerOrTargetMotionResets(){ready(0);ready(1);ready(2);assertTrue(tracker.observe(frame(3,entity,uuid,new Vec3(1,72,0),new Vec3(1,72,3),0,true),settings).isEmpty());}
    @Test void everyScopeIdentityAndPolicyAndPlotInterrupts(){var fields=List.of(scope.player(),scope.world(),scope.connection(),scope.farm(),scope.config(),scope.camera(),scope.policy());for(int i=0;i<8;i++){tracker.reset();ready(0);ready(1);ready(2);Object[] f=fields.toArray();if(i<7)f[i]=new Object();var foreign=new NearbyPestTracker.Scope(f[0],f[1],f[2],f[3],f[4],f[5],f[6],i==7?2:1);var original=frame(3);assertTrue(tracker.observe(new NearbyPestTracker.Observation(foreign,3,original.playerEye(),0,original.target(),true,4.5),settings).isEmpty());}}
    @Test void alteredLocalPolicyCannotBorrowOldDwell(){ready(0);ready(1);ready(2);assertTrue(tracker.observe(frame(3),new NearbyPestTracker.Settings(100,3,.5)).isEmpty());}
    @Test void invalidAndNonfiniteGeometryDoNotQualify(){ready(0);ready(1);assertTrue(tracker.observe(frame(2,entity,uuid,new Vec3(Double.NaN,72,0),new Vec3(0,72,3),0,true),settings).isEmpty());assertFalse(ready(3));assertTrue(tracker.observe(null,settings).isEmpty());}
    @Test void freshClaimMustMatchExactNativeFrameAndIssuer(){ready(0);ready(1);ready(2);var claim=tracker.observe(frame(3),settings).orElseThrow();assertTrue(tracker.current(claim,frame(3),settings));assertFalse(tracker.current(claim,frame(4),settings));assertFalse(tracker.current(claim,frame(3,entity,uuid,new Vec3(.01,72,0),new Vec3(0,72,3),0,true),settings));assertFalse(new NearbyPestTracker().current(claim,frame(3),settings));}
    @Test void previewDoesNotRetireButActualAttemptSurvivesReset(){ready(0);ready(1);ready(2);var claim=tracker.observe(frame(3),settings).orElseThrow();assertTrue(tracker.current(claim,frame(3),settings));assertTrue(tracker.attempted(claim));assertFalse(tracker.attempted(claim));tracker.reset();for(int i=4;i<12;i++)assertFalse(ready(i));}
    @Test void retiredServerUuidCannotReenterThroughAReplacementClientObject(){ready(0);ready(1);ready(2);tracker.attempted(tracker.observe(frame(3),settings).orElseThrow());tracker.reset();for(int i=4;i<12;i++)assertTrue(tracker.observe(frame(i,new Object(),uuid,new Vec3(0,72,0),new Vec3(0,72,3),0,true),settings).isEmpty());}
    @Test void otherAttemptDoesNotReviveOldNativeEntity(){ready(0);ready(1);ready(2);assertTrue(tracker.attempted(tracker.observe(frame(3),settings).orElseThrow()));Object other=new Object();for(int i=4;i<8;i++){var c=tracker.observe(frame(i,other,UUID.fromString("12345678-1234-1234-1234-123456789abc"),new Vec3(0,72,0),new Vec3(0,72,3),0,true),settings);if(c.isPresent())tracker.attempted(c.get());}tracker.reset();for(int i=9;i<16;i++)assertFalse(ready(i));}
    @Test void originalDeadlinesAreNotPolicyDefaults(){assertThrows(IllegalArgumentException.class,()->new NearbyPestTracker.Settings(0,3,.5));assertThrows(IllegalArgumentException.class,()->new NearbyPestTracker.Settings(90,0,.5));assertThrows(IllegalArgumentException.class,()->new NearbyPestTracker.Settings(90,3,Double.POSITIVE_INFINITY));}
    @Test void explicitEditableFarmingUiAndPersistenceUseClosedDefaults(){var rows=SettingsContent.build().forCategory("Farming").rows();assertFalse(PestAutoAdmissionConfig.PEST_NEARBY_ENABLED.defaultValue());for(var key:List.of(PestAutoAdmissionConfig.PEST_NEARBY_ENABLED,PestAutoAdmissionConfig.PEST_NEARBY_FOV_DEGREES,PestAutoAdmissionConfig.PEST_NEARBY_DWELL_TICKS,PestAutoAdmissionConfig.PEST_NEARBY_MAXIMUM_STEP)){assertTrue(PersistableKeys.all().contains(key));assertEquals(1,rows.stream().filter(r->key.name().equals(r.configKey())&&r.enabled()).count());}assertEquals(0,PestAutoAdmissionConfig.PEST_NEARBY_DWELL_TICKS.defaultValue());}
}
